import json,numpy as np
from pathlib import Path
Path('models').mkdir(exist_ok=True)
FR=json.load(open('fourier_results.json'))['100']; ER=json.load(open('extended_results.json'))
DATA='`data/train.csv`, all three trajectories and all within-trajectory transitions: `447` transitions (`149` per trajectory). Initial states are the first logged states; no transitions join different trajectories. No data were withheld from the final coefficient fits. Structure and estimation settings were compared using leave-one-trajectory-out validation, each time fitting on the other two complete trajectories. Sampling period is `0.2` s; coefficients below are per-sample displacements, not continuous-time rates. Column units were not supplied.'
LIMIT='Only three trajectories, all starting at the same zero state, were supplied; units, system identity and hidden dynamics are unknown. Interpreting `x2` as an angle in the trigonometric arguments is an empirical convention, supported by wrapping at `pi`, not supplied physical metadata. Prediction outside the observed input/state ranges is unvalidated. Input-change residuals and serial correlations remain, consistent with omitted dynamics; the permitted memoryless state map cannot explicitly represent actuator-rate states or previous inputs. Parameters are effective prediction coefficients, not claimed physical constants. Angular errors in fitting are reduced to the principal interval using `atan2(sin(error), cos(error))`.'

def row(name,val,desc,unit='not supplied'):
 return {'name':name,'value':float(val),'unit':unit,'type':'fitted','description':desc}
def save(label,obj):
 json.dump(obj,open('models/'+label+'.json','w'),indent=2)

def fmtvec(vec):return '`['+', '.join(format(float(a),'.16g') for a in vec)+']`'
# Independent Fourier-feature map.
basis=['x3*cos(x2)','x3*sin(x2)','cos(x2)','sin(x2)','x3*x4*cos(x2)','x3*x4*sin(x2)']
p=FR['params']; rows=[];expr={}
for j,key in enumerate(['y_next','x1_next']):
 state=['y','x1'][j]; terms=[]
 for i,term in enumerate(basis):
  name='c'+str(j*6+i);terms.append(name+'*'+term)
  rows.append(row(name,p[j*6+i],f'Coefficient of `{term}` in `{key}`; estimated first by ordinary least squares and then jointly by regularized free-run nonlinear least squares. Its mathematical effect is a direction-dependent position increment.'))
 expr[key]=state+' + '+' + '.join(terms)
h='(turn_gain*sign(x4)*Max(Abs(x4)-turn_width,0) + turn_bias)'
expr['x2_next']='atan2(sin(x2 + '+h+'), cos(x2 + '+h+'))'
rows += [row('turn_gain',p[12],'Slope of the odd dead-zone turning increment outside its width.'),row('turn_bias',p[13],'Constant angular increment per sample; an empirical drift, not a known torque.'),row('turn_width',p[14],'Width of the symmetric dead zone in `x4`; inside it only `turn_bias` remains.')]
train=float(np.sqrt(np.mean(np.array(FR['train'])**2))); cv=float(np.sqrt(np.mean(np.array(FR['cv'])**2)))
save('FourierRidge',{'expressions':expr,'parameters':rows,'estimation':{
 'criterion':'First minimize unweighted squared one-step errors of `y_next-y` and `x1_next-x1` separately, and squared principal angular-increment error for the turning law. Then jointly minimize full free-run squared errors, with residual weights `[1, 0.15, 0.1]` for `y`, `x1`, `x2`, plus `100*sum((c_i-c_i_initial)**2)` over the twelve position coefficients. Weights and penalty strength are numerical fitting conventions because native units are unspecified: the score concerns `y`, auxiliary-state penalties preserve useful state behavior, and anchoring to one-step estimates reduces rollout overfitting. Penalty strengths `[0, 1, 10, 100]` were compared on held-out trajectories; `100` gave the smallest pooled validation error.',
 'data':DATA,
 'method':'For position coefficients, ordinary least squares using `numpy.linalg.lstsq`, which needs no starts because the feature fit is linear. Angular coefficients are initialized by bounded nonlinear least squares using `scipy.optimize.least_squares` (default trust-region reflective method), starting from `[0.15, 0, 0.08]` for `[turn_gain, turn_bias, turn_width]`, a near-linear positive-turn initial hypothesis. Its bounds are `0 <= turn_gain <= 0.5`, `-0.02 <= turn_bias <= 0.02`, `0 <= turn_width <= 0.4`, in unknown native coefficient units. Next all fifteen coefficients are estimated together in regularized nonlinear least squares with the same function, initialized at '+fmtvec(FR['initial'])+' in order `[c0, c1, c2, c3, c4, c5, c6, c7, c8, c9, c10, c11, turn_gain, turn_bias, turn_width]`. Position coefficients satisfy `-2 <= c_i <= 2` (unknown native units), a loose guard against very large cancellation; angular bounds remain as above. Rollout optimization uses `max_nfev = 400` and `ftol = xtol = gtol = 1e-9`; these are dimensionless numerical solver settings. This staged method exploits linear one-step initialization, then explicitly targets repeated simulation rather than only local accuracy. No random draws or seeds apply.',
 'script':'reproduce_final.py'},'discussion':{
 'family':'Discrete-time nonlinear state-space map with Fourier/polynomial features and regularized nonlinear output-error estimation. The position updates are linear combinations of specified features, not neural-network predictions. The penalty is a centered ridge/Tikhonov penalty; see A. E. Hoerl and R. W. Kennard, Ridge Regression: Biased Estimation for Nonorthogonal Problems, Technometrics (1970), cited from memory without online verification.',
 'interpretation':'`y`, `x1`, `x2` are the current states; `x3`, `x4` are the current inputs; `_next` denotes the next sample. `c0` through `c11` independently weight the six stated basis functions for each position coordinate. `x3*cos(x2)` and `x3*sin(x2)` are input-scaled directional increments; `cos(x2)` and `sin(x2)` allow a direction-dependent input-independent drift; `x3*x4*cos(x2)` and `x3*x4*sin(x2)` allow bilinear steering-direction modulation. Independent coefficients allow mild anisotropy and cross-direction response without assuming identical gains. `turn_gain*sign(x4)*Max(Abs(x4)-turn_width,0)` is an odd piecewise-linear response with a central dead zone, and `turn_bias` is additive angular drift. `atan2(sin(x2 + '+h+'), cos(x2 + '+h+'))` enforces the observed principal-angle convention.',
 'origin':'The raw affine and degree-two/degree-three polynomial increment fits had poor angular residuals because they ignored wrapping. Directional projection of measured position increments supported sine/cosine features, suggesting an empirical kinematic structure. These two leading features were data-motivated, not given physics. Constant directional terms and the bilinear input terms were deliberately proposed to accommodate observed drift and within-step turning errors; no genetic symbolic regression was run. Independent coordinate coefficients relax the shared-speed constraint of the simpler candidates. The dead-zone angular structure was selected after comparing linear, cubic, hard-dead-zone and smooth rational input laws. Unregularized Fourier rollout fits overfit held-out trajectories, motivating the centered coefficient penalty. Pooled training `y` rollout RMSE is `'+format(train,'.6g')+'` native `y` units (unspecified), and pooled leave-one-trajectory-out `y` RMSE is `'+format(cv,'.6g')+'` in the same units; both exclude the initial sample.',
 'limitations':LIMIT+' Residual diagnostics in `final_residual_report.txt` show much larger angular errors at the first sample after input changes than later in the input block. The dead-zone response can also produce nonsmooth parameter-estimation objectives; the reported optimizer is a local solution, not a certified global minimum.'}})
# Three compact alternative structures.
for label,f,mode in [('Deadzone','hard_phase','y'),('Rational','soft_phase','y'),('Periodic','periodic','balanced')]:
 r=ER[f][mode];p=r['params'];names=['speed_gain','speed_bias','turn_gain','turn_bias','turn_width','direction_factor','direction_bias']
 desc=['Input coefficient in the common displacement magnitude.','Input-independent common displacement increment.','Scale coefficient in the turning response.','Additive angular increment per sample.','Dead-zone width in the turning input, or rational smoothing width.','Multiplier of the predicted angular increment in the displacement direction; estimated to accommodate within-sample motion and omitted transients.','Additive shift in the displacement direction.']
 if f=='periodic':names+=['sine_bias','cosine_bias'];desc+=['Coefficient of `sin(x2)` in the angular increment.','Coefficient of `cos(x2)` in the angular increment.']
 rows=[row(n,p[i],desc[i],'-' if n=='direction_factor' else 'not supplied') for i,n in enumerate(names)]
 v='(speed_gain*x3 + speed_bias)'
 if f=='soft_phase': h='(turn_gain*x4**3/(x4**2 + turn_width**2) + turn_bias)'
 else:h='(turn_gain*sign(x4)*Max(Abs(x4)-turn_width,0) + turn_bias)'
 if f=='periodic':h='('+h+' + sine_bias*sin(x2) + cosine_bias*cos(x2))'
 direction='(x2 + direction_factor*'+h+' + direction_bias)'
 expr={'y_next':'y + '+v+'*cos'+direction,'x1_next':'x1 + '+v+'*sin'+direction,'x2_next':'atan2(sin(x2 + '+h+'), cos(x2 + '+h+'))'}
 weights='[1, 0.15, 0.1]' if mode=='y' else '[1, 1, 0.3]'
 initial=[.16,0,.19,.001,.1,-.4,0] if f!='soft_phase' else [.16,0,.19,.001,.1,-.4,0]
 if f=='periodic':initial += [0,0]
 boundtext='`0 <= speed_gain <= 0.4`, `-0.01 <= speed_bias <= 0.01`, `0 <= turn_gain <= 0.5`, `-0.02 <= turn_bias <= 0.02`, `0 <= turn_width <= 0.4`, `-3 <= direction_factor <= 2`, `-0.5 <= direction_bias <= 0.5`'
 if f=='soft_phase':boundtext=boundtext.replace('`0 <= turn_width <= 0.4`','`0.001 <= turn_width <= 0.7`')
 if f=='periodic':boundtext+=', `-0.01 <= sine_bias <= 0.01`, `-0.01 <= cosine_bias <= 0.01`'
 cv=float(np.sqrt(np.mean(np.array(r['cv'])[:,0]**2)));train=float(np.sqrt(np.mean(np.array(r['train'])[:,0]**2)))
 family='Kinematic unicycle-like discrete-time state map with '
 if f=='hard_phase':family+='a hard-dead-zone static input response.'
 elif f=='soft_phase':family+='a smooth rational static input response.'
 else:family+='a sparse first-harmonic angular feedback correction and hard-dead-zone input response.'
 family+=' For the basic directional kinematic structure, see S. M. LaValle, Planning Algorithms, Cambridge University Press (2006), differential constraints chapter, cited from memory without online verification. No supplied system description establishes that this is physically a vehicle.'
 origin='State wrapping and observed alignment of displacement with `x2` motivated common directional increments. Shared displacement magnitude and additive angular increments are a deliberately parsimonious kinematic hypothesis; the system identity remains unknown. Affine and polynomial increment maps, linear-input kinematics, and cubic angular-input laws were examined first. Hard dead zones improved leave-one-trajectory-out simulation relative to the linear/cubic laws. The estimated direction factor and offset were proposed after residuals concentrated at input changes, to approximate averaging and omitted transients without introducing unavailable lag variables.'
 if f=='soft_phase':origin+=' This candidate replaces the nonsmooth dead-zone operator with the guessed rational odd function `x4**3/(x4**2 + turn_width**2)`: it suppresses small inputs smoothly and becomes approximately linear for large inputs. It represents uncertainty about whether a sharp threshold is warranted.'
 if f=='periodic':origin+=' The proposed terms `sine_bias*sin(x2)` and `cosine_bias*cos(x2)` allow a bounded orientation-dependent angular residual. They were an empirical alternative to radial position-dependent speed correction and saturation/asymmetric dead-zone fits, not a known force law. They reduced balanced-state trajectory error; the balanced residual weights were retained because they validated better for this particular family than the output-emphasized weights.'
 origin+=' Pooled training `y` free-run RMSE is `'+format(train,'.6g')+'` native `y` units (unspecified); pooled leave-one-trajectory-out `y` RMSE is `'+format(cv,'.6g')+'` in the same units, excluding each initial sample.'
 interpretation='`y`, `x1`, `x2` are current states, `x3`, `x4` are current inputs, and `_next` denotes the next sample. '+v+' is the common signed displacement magnitude per sample. '+h+' is the angular increment. '+direction+' is the direction used for the position displacement; `direction_factor` and `direction_bias` are effective fitted adjustments, not claims of known physical averaging. The projections `'+v+'*cos'+direction+'` and `'+v+'*sin'+direction+'` update the two coordinates. `atan2(sin(x2 + '+h+'), cos(x2 + '+h+'))` wraps the angular update.'
 if f=='soft_phase':interpretation+=' The rational term tends cubically to zero near the origin and approaches a linear input law far beyond `turn_width`; its positive denominator avoids singularities.'
 else:interpretation+=' The `sign(x4)*Max(Abs(x4)-turn_width,0)` term suppresses small inputs and is odd outside its central dead zone.'
 if f=='periodic':interpretation+=' The angular terms `sine_bias*sin(x2)` and `cosine_bias*cos(x2)` are bounded first-harmonic direction-dependent corrections; no physical mechanism is identified.'
 save(label,{'expressions':expr,'parameters':rows,'estimation':{
  'criterion':'Initialization minimizes the sum of squared discrepancies of displacement magnitude and angular increment using residuals `[v - 0.2*q0, 0.3*(h-q1)]`, where `q0` is measured displacement projected on the midpoint direction and divided by `0.2` s and `q1` is the principal observed angular increment. The initial criterion uses input-only `h`, even for Periodic. Then minimize full free-run squared state errors, with residual weights `'+weights+'` in the order `y`, `x1`, `x2`. Numerical weights are empirical fitting conventions because units are unknown; simulated `y` is the scored output, while auxiliary errors discourage implausible state paths. All initial samples are excluded from the objective.',
  'data':DATA,
  'method':'Bounded nonlinear least squares with `scipy.optimize.least_squares`, default trust-region reflective method, both stages. This handles the nonlinear width and multi-step dependence; ordinary least squares cannot optimize these jointly. Initialization starts from '+fmtvec(initial)+' in order '+ '`['+', '.join(names)+']`'+', representing a small positive input gain, small drift, moderate dead-zone width and direction-lag hypothesis. The actual second-stage start is '+fmtvec(r['initial'])+' in the same order. Both stages include all coefficients in the optimizer vector; `direction_factor`, `direction_bias` and any angular harmonic coefficients do not affect the first-stage input-only criterion and retain their initial values until the joint rollout fit. First-stage settings are `max_nfev = 100` with other tolerances at SciPy defaults; second-stage settings are `max_nfev = 200`, `ftol = xtol = gtol = 1e-9`. Bounds are '+boundtext+'; except the dimensionless `direction_factor`, native coefficient units are unknown. Bounds are loose numerical guards for gains/drifts; positive rational width prevents division by zero. No random numbers are used; no seed applies. All final parameters are estimated together in the second stage.',
  'script':'reproduce_final.py'},'discussion':{'family':family,'interpretation':interpretation,'origin':origin,'limitations':LIMIT+' The common-magnitude constraint may miss directional anisotropy. The direction correction does not actually supply an actuator-memory state; validation cannot guarantee extrapolation to other input switching rates.'}})
json.dump({'order':['FourierRidge','Deadzone','Rational','Periodic'],'recommended':'FourierRidge','reason':'The regularized Fourier-feature map has the lowest pooled leave-one-trajectory-out free-running `y` RMSE: `0.061109` native `y` units (not supplied), across the three training trajectories with each validation trajectory fitted using only the other two. Its separate coordinate maps relax the shared-displacement hypothesis, while a centered ridge penalty prevents the poor validation of unregularized fits. No test data were accessed. Deadzone, Rational and Periodic retain compact alternative hard-threshold, smooth-rational and angular-feedback structures; their validation errors are larger. Residuals still suggest omitted input-response dynamics, so the recommendation is comparative, not a claim of exact identification.'},open('models/pool.json','w'),indent=2)
